function safeCathayDiagnosticUrl(value) {
  try {
    const url = new URL(value);
    return `${url.origin}${url.pathname}`;
  } catch {
    return "invalid-url";
  }
}
function safeCathayDiagnosticOrigin(value) {
  try {
    return new URL(value).origin;
  } catch {
    return "invalid-origin";
  }
}
function safeCathayDiagnosticMessage(value, secrets = []) {
  let sanitized = value.replace(/https?:\/\/[^\s"'<>]+/gi, (url) => safeCathayDiagnosticUrl(url)).replace(/[A-Za-z0-9_-]{16,}/g, "[redacted]");
  for (const secret of secrets) {
    if (secret)
      sanitized = sanitized.split(secret).join("[redacted]");
  }
  return sanitized.slice(0, 240);
}
function attachCathaySafeDiagnostics(page, config) {
  const ignoredAbortedOrigins = new Set([
    "https://ad.doubleclick.net",
    "https://analytics.google.com",
    "https://cathayunitedbank.tt.omtrdc.net",
    "https://faro-collector-prod-ap-southeast-1.grafana.net",
    "https://www.google.com"
  ]);
  const recordedResponses = new Set;
  const recordedFailures = new Set;
  const secrets = [
    config.userId,
    config.account,
    config.password,
    config.otp
  ].filter((value) => Boolean(value));
  page.on("pageerror", (error) => {
    const diagnostic = JSON.stringify({
      event: "cathaybk_page_error",
      errorType: error.name,
      message: safeCathayDiagnosticMessage(error.message, secrets)
    });
    if (error.name === "ReferenceError" && error.message.includes("getMbox")) {
      console.warn(diagnostic);
      return;
    }
    console.error(diagnostic);
  });
  page.on("requestfailed", (request) => {
    const origin = safeCathayDiagnosticOrigin(request.url());
    const errorText = safeCathayDiagnosticMessage(request.failure()?.errorText ?? "unknown", secrets);
    if (errorText === "net::ERR_ABORTED" && ignoredAbortedOrigins.has(origin)) {
      return;
    }
    const key = `${origin}:${errorText}`;
    if (recordedFailures.size >= 20 || recordedFailures.has(key))
      return;
    recordedFailures.add(key);
    console.warn(JSON.stringify({
      event: "cathaybk_request_failed",
      origin,
      errorText
    }));
  });
  page.on("response", (response) => {
    const status = response.status();
    if (status < 400)
      return;
    const origin = safeCathayDiagnosticOrigin(response.url());
    const key = `${origin}:${status}`;
    if (recordedResponses.size >= 20 || recordedResponses.has(key))
      return;
    recordedResponses.add(key);
    console.warn(JSON.stringify({
      event: "cathaybk_http_error",
      origin,
      status
    }));
  });
}
