async function scrapeDomAccounts(page) {
  return page.evaluate(() => {
    const results = [];
    const buttons = Array.from(document.querySelectorAll("button"));
    for (const btn of buttons) {
      const text = btn.textContent?.trim() ?? "";
      if (!/^\d{10,}$/.test(text))
        continue;
      let el = btn;
      for (let i = 0;i < 10; i++) {
        el = el?.parentElement ?? null;
        if (!el)
          break;
        const rowText = el.innerText?.trim() ?? "";
        if (rowText.includes("$") && rowText.length < 200) {
          const amounts = rowText.match(/\$([\d,]+)/g) ?? [];
          const parseAmt = (s) => parseInt(s.replace(/[$,]/g, ""), 10) || 0;
          results.push({
            acctNo: text,
            accountTypeName: rowText.split(text)[0]?.replace(/[●\s]+/g, " ").trim() || "臺幣存款",
            balance: amounts[0] ? parseAmt(amounts[0]) : 0,
            availableBalance: amounts[1] ? parseAmt(amounts[1]) : 0,
            currency: "TWD"
          });
          break;
        }
      }
    }
    return results;
  });
}
